steps.run:
$windowsPowerShell = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not (Test-Path -LiteralPath $windowsPowerShell -PathType Leaf)) {
  throw 'Windows PowerShell 5.1 executable is missing from the runner.'
}

# Keep the legacy developer recorder compatible with Windows PowerShell
# 5.1, but human testing no longer depends on unsigned script execution.
$recorderBytes = [System.IO.File]::ReadAllBytes('scripts/manual-compatibility-v201.ps1')
if (@($recorderBytes | Where-Object { $_ -gt 127 }).Count -ne 0) {
  throw 'manual-compatibility-v201.ps1 must remain ASCII-only for Windows PowerShell 5.1 compatibility.'
}

$output = Join-Path $env:RUNNER_TEMP "compatibility-results-2.0.1.md"
& $windowsPowerShell -NoProfile -ExecutionPolicy Bypass -File .\scripts\manual-compatibility-v201.ps1 -ScaffoldOnly -OutputPath $output
if ($LASTEXITCODE -ne 0) {
  throw "Windows PowerShell 5.1 recorder smoke test failed with exit code $LASTEXITCODE."
}
if (-not (Test-Path -LiteralPath $output -PathType Leaf)) {
  throw 'Manual compatibility recorder did not create its result file.'
}
$text = Get-Content -LiteralPath $output -Raw
if ($text -notmatch '## Manual application matrix' -or $text -notmatch 'Notepad' -or $text -notmatch 'Windows Terminal' -or $text -notmatch 'PENDING') {
  throw 'Manual compatibility recorder produced an incomplete scaffold.'
}

& $windowsPowerShell -NoProfile -ExecutionPolicy Bypass -File .\scripts\verify-compatibility-v201.ps1 -Path $output
if ($LASTEXITCODE -eq 0) {
  throw 'PowerShell compatibility verifier unexpectedly accepted a PENDING scaffold.'
}
$global:LASTEXITCODE = 0

$compiledScaffold = Join-Path $env:RUNNER_TEMP "compatibility-compiled-scaffold-2.0.1.md"
& .\target\debug\g-switcher-compatibility.exe scaffold $compiledScaffold
if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $compiledScaffold -PathType Leaf)) {
  throw 'Compiled compatibility recorder failed to create a scaffold.'
}
& .\target\debug\g-switcher-compatibility.exe verify $compiledScaffold
if ($LASTEXITCODE -eq 0) {
  throw 'Compiled compatibility verifier unexpectedly accepted a PENDING scaffold.'
}
$global:LASTEXITCODE = 0

$valid = @'
# G-switcher 2.0.1 - compatibility verifier fixture

## Manual application matrix

| Application | Version tested | Windows build | Auto | Manual current word | Selected text | Undo | Password/sensitive fields | Result / notes |
|---|---|---|---|---|---|---|---|---|
| Notepad | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | N/A | fixture |
| Microsoft Word | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | N/A | fixture |
| Microsoft Edge | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | PASS | fixture |
| Google Chrome | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | PASS | fixture |
| Telegram Desktop | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | N/A | fixture |
| Visual Studio Code | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | N/A | fixture |
| Windows Terminal | 1.0.0 | 26100 | UNSUPPORTED/FAIL-OPEN | UNSUPPORTED/FAIL-OPEN | UNSUPPORTED/FAIL-OPEN | N/A | N/A | fixture |

## End fixture
'@
$validPath = Join-Path $env:RUNNER_TEMP "compatibility-valid-2.0.1.md"
Set-Content -LiteralPath $validPath -Value $valid -Encoding UTF8

& $windowsPowerShell -NoProfile -ExecutionPolicy Bypass -File .\scripts\verify-compatibility-v201.ps1 -Path $validPath
if ($LASTEXITCODE -ne 0) {
  throw 'PowerShell compatibility verifier rejected a complete non-blocking matrix.'
}
& .\target\debug\g-switcher-compatibility.exe verify $validPath
if ($LASTEXITCODE -ne 0) {
  throw 'Compiled compatibility verifier rejected a complete non-blocking matrix.'
}

$invalidBrowser = $valid.Replace(
  '| Microsoft Edge | 1.0.0 | 26100 | PASS | PASS | PASS | PASS | PASS |',
  '| Microsoft Edge | 1.0.0 | 26100 | UNSUPPORTED/FAIL-OPEN | PASS | PASS | PASS | PASS |'
)
$invalidBrowserPath = Join-Path $env:RUNNER_TEMP "compatibility-invalid-browser-2.0.1.md"
Set-Content -LiteralPath $invalidBrowserPath -Value $invalidBrowser -Encoding UTF8
& $windowsPowerShell -NoProfile -ExecutionPolicy Bypass -File .\scripts\verify-compatibility-v201.ps1 -Path $invalidBrowserPath
if ($LASTEXITCODE -eq 0) {
  throw 'PowerShell verifier unexpectedly accepted unsupported Edge core behavior.'
}
$global:LASTEXITCODE = 0
& .\target\debug\g-switcher-compatibility.exe verify $invalidBrowserPath
if ($LASTEXITCODE -eq 0) {
  throw 'Compiled verifier unexpectedly accepted unsupported Edge core behavior.'
}
$global:LASTEXITCODE = 0

$invalidCore = $valid.Replace(
  '| Notepad | 1.0.0 | 26100 | PASS |',
  '| Notepad | 1.0.0 | 26100 | N/A |'
)
$invalidCorePath = Join-Path $env:RUNNER_TEMP "compatibility-invalid-core-2.0.1.md"
Set-Content -LiteralPath $invalidCorePath -Value $invalidCore -Encoding UTF8
& .\target\debug\g-switcher-compatibility.exe verify $invalidCorePath
if ($LASTEXITCODE -eq 0) {
  throw 'Compiled verifier unexpectedly accepted N/A for a core text-operation column.'
}
$global:LASTEXITCODE = 0

$invalidMetadata = $valid.Replace(
  '| Microsoft Word | 1.0.0 | 26100 |',
  '| Microsoft Word | UNKNOWN | 26100 |'
)
$invalidMetadataPath = Join-Path $env:RUNNER_TEMP "compatibility-invalid-metadata-2.0.1.md"
Set-Content -LiteralPath $invalidMetadataPath -Value $invalidMetadata -Encoding UTF8
& .\target\debug\g-switcher-compatibility.exe verify $invalidMetadataPath
if ($LASTEXITCODE -eq 0) {
  throw 'Compiled verifier unexpectedly accepted UNKNOWN application metadata.'
}
$global:LASTEXITCODE = 0

$arguments = @(
  'test', '--locked', '--test', 'browser_uia_adapter', '--',
  '--ignored', '--test-threads=1', '--nocapture'
)
$process = Start-Process -FilePath 'cargo.exe' -ArgumentList $arguments -PassThru -NoNewWindow
if (-not $process.WaitForExit(240000)) {
  Write-Host 'Browser UIA E2E exceeded 240 seconds; terminating cargo and descendants.'
  & taskkill.exe /PID $process.Id /T /F | Out-Host
  throw 'Real Edge/Chrome UIA adapter E2E timed out.'
}
$process.WaitForExit()
if ($process.ExitCode -ne 0) {
  throw "Real Edge/Chrome UIA adapter E2E failed with exit code $($process.ExitCode)."
}

$ErrorActionPreference = 'Stop'
if ($env:GITHUB_ACTIONS -ne 'true') { throw 'Ephemeral CI host only' }
Remove-Item -LiteralPath 'HKCU:\Software\GSwitcher' -Recurse -Force -ErrorAction SilentlyContinue
Add-Type -AssemblyName System.Drawing
Add-Type @'
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public class LayoutQA {
 [StructLayout(LayoutKind.Sequential)] public struct R { public int left,top,right,bottom; }
 public delegate bool Callback(IntPtr h,IntPtr p);
 [DllImport("user32.dll")] public static extern bool EnumChildWindows(IntPtr h,Callback cb,IntPtr p);
 [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h,out R r);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h,out R r);
 [DllImport("user32.dll")] public static extern int MapWindowPoints(IntPtr a,IntPtr b,ref R r,uint n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h,StringBuilder s,int n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr h,StringBuilder s,int n);
 [DllImport("user32.dll")] public static extern IntPtr GetDC(IntPtr h);
 [DllImport("user32.dll")] public static extern int ReleaseDC(IntPtr h,IntPtr dc);
 [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
 [DllImport("gdi32.dll")] public static extern IntPtr SelectObject(IntPtr dc,IntPtr o);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int DrawText(IntPtr dc,string s,int n,ref R r,uint f);
 [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h,IntPtr dc,uint f);
 [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
 public class Row { public string text; public string cls; public int x,y,width,height,needed; }
 public static List<Row> Inspect(IntPtr parent) {
  R client; GetClientRect(parent,out client); var rows=new List<Row>();
  EnumChildWindows(parent,(h,p)=> {
   var text=new StringBuilder(4096); var cls=new StringBuilder(128); GetWindowText(h,text,text.Capacity); GetClassName(h,cls,cls.Capacity);
   R rect; GetWindowRect(h,out rect); MapWindowPoints(IntPtr.Zero,parent,ref rect,2);
   var row=new Row {text=text.ToString(),cls=cls.ToString(),x=rect.left,y=rect.top,width=rect.right-rect.left,height=rect.bottom-rect.top};
   if (row.cls=="Static" && row.text.Length>0) {
    var dc=GetDC(h); var font=SendMessage(h,0x31,IntPtr.Zero,IntPtr.Zero); var old=SelectObject(dc,font);
    var measured=new R {right=row.width}; DrawText(dc,row.text,row.text.Length,ref measured,0x400|0x10|0x800);
    SelectObject(dc,old); ReleaseDC(h,dc); row.needed=measured.bottom-measured.top;
    if(row.needed>row.height || row.y+row.height>client.bottom) throw new Exception("Clipped static: "+row.text);
   }
   rows.Add(row); return true;
  },IntPtr.Zero); return rows;
 }
}
'@
$exe = (Resolve-Path 'target/release/g-switcher.exe').Path
$p = Start-Process -FilePath $exe -PassThru
try {
  $deadline = [DateTime]::UtcNow.AddSeconds(30)
  do { Start-Sleep -Milliseconds 200; $p.Refresh(); $hwnd = $p.MainWindowHandle } while ($hwnd -eq 0 -and -not $p.HasExited -and [DateTime]::UtcNow -lt $deadline)
  if ($hwnd -eq 0) { throw 'First-run window missing' }
  Start-Sleep -Milliseconds 400
  $rows = [LayoutQA]::Inspect($hwnd)
  if (@($rows | Where-Object { $_.text -like '*Управление*' }).Count -eq 0) { throw 'Unexpected window' }
  $out = Join-Path $env:RUNNER_TEMP 'first-run-layout-qa'
  New-Item -ItemType Directory -Force -Path $out | Out-Null
  $rows | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $out 'layout.json') -Encoding utf8
  $r = New-Object LayoutQA+R
  [LayoutQA]::GetWindowRect($hwnd,[ref]$r) | Out-Null
  $bmp = [System.Drawing.Bitmap]::new(($r.right-$r.left),($r.bottom-$r.top))
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $dc = $g.GetHdc()
  try { if (-not [LayoutQA]::PrintWindow($hwnd,$dc,0)) { throw 'PrintWindow failed' } } finally { $g.ReleaseHdc($dc) }
  $bmp.Save((Join-Path $out 'first-run.png'),[System.Drawing.Imaging.ImageFormat]::Png)
  $g.Dispose(); $bmp.Dispose()
  Write-Host "FIRST_RUN_LAYOUT_PASS controls=$($rows.Count)"
} finally {
  if (-not $p.HasExited) { [LayoutQA]::PostMessage($p.MainWindowHandle,0x10,[IntPtr]::Zero,[IntPtr]::Zero) | Out-Null; if (-not $p.WaitForExit(5000)) { $p.Kill(); $p.WaitForExit() } }
}

$mpCmd = @(
  "$env:ProgramFiles\Windows Defender\MpCmdRun.exe",
  "$env:ProgramData\Microsoft\Windows Defender\Platform\*\MpCmdRun.exe"
) | ForEach-Object { Get-Item $_ -ErrorAction SilentlyContinue } | Sort-Object FullName -Descending | Select-Object -First 1
if ($null -eq $mpCmd) {
  Write-Warning 'Microsoft Defender command-line scanner is unavailable on this runner; other release gates continue.'
  exit 0
}
foreach ($path in @('target/release/g-switcher.exe', 'target/release/g-switcher-compatibility.exe')) {
  & $mpCmd.FullName -Scan -ScanType 3 -File (Resolve-Path $path).Path -DisableRemediation
  if ($LASTEXITCODE -ne 0) {
    throw "Microsoft Defender scan failed or detected a threat for $path (exit $LASTEXITCODE)."
  }
}
